function evaluateExpression(expression) {
  // Check for invalid characters
  if (!/^[\d+\-*/^()\s]+$/.test(expression)) {
    return "Error: Invalid characters in expression";
  }

  // Replace all occurrences of "--" with "+"
  expression = expression.replace(/--/g, "+");

  // Evaluate parentheses first
  while (/\([^()]+\)/.test(expression)) {
    expression = expression.replace(/\([^()]+\)/g, function(match) {
      return evaluateExpression(match.slice(1, -1));
    });
  }

  // Evaluate exponents next
  while (/\d+\^\d+/.test(expression)) {
    expression = expression.replace(/(\d+)\^(\d+)/g, function(match, p1, p2) {
      return Math.pow(parseFloat(p1), parseFloat(p2));
    });
  }

  // Evaluate multiplication and division next
  while (/[\d.]+[*/][\d.]+/.test(expression)) {
    expression = expression.replace(/([\d.]+)([*/])([\d.]+)/g, function(match, p1, p2, p3) {
      return (p2 === "*") ? (parseFloat(p1) * parseFloat(p3)) : (parseFloat(p1) / parseFloat(p3));
    });
  }

  // Evaluate addition and subtraction last
  while (/[\d.]+[+\-][\d.]+/.test(expression)) {
    expression = expression.replace(/([\d.]+)([+\-])([\d.]+)/g, function(match, p1, p2, p3) {
      return (p2 === "+") ? (parseFloat(p1) + parseFloat(p3)) : (parseFloat(p1) - parseFloat(p3));
    });
  }

  // Return the final result as a number
  return parseFloat(expression);
}

// Example usage:
console.log(evaluateExpression("2 + 3 * 4"));  // output: 14
console.log(evaluateExpression("(2 + 3) * 4"));  // output: 20
console.log(evaluateExpression("10^-2 + 5"));  // output: 5.01
console.log(evaluateExpression("-10 * (-1 + 2)"));  // output: 20
console.log(evaluateExpression("1/0"));  // output: Infinity
console.log(evaluateExpression("3 / 2"));  // output: 1.5
console.log(evaluateExpression("2 + 3 * abc"));  // output: Error: Invalid characters in expression
